package main
import("testing";"math";"os";"path/filepath";"encoding/json";"encoding/binary";"crypto/sha256";"fmt";"encoding/csv";"strconv")
type forward_spec struct { Rate int `json:"rate"`; Shape string `json:"shape"`; CarrierPhase float64 `json:"carrier_phase"`; LFOPhase float64 `json:"lfo_phase"`; Age float64 `json:"native_latch_age"`; PhaseSteps int `json:"generic_phase_steps"`; Quantizer string `json:"pcm_quantizer"`; Amplitude float64 `json:"amplitude"`; NativeIncrement int `json:"native_increment"`; PeriodScale float64 `json:"true_period_scale"` }
func TestFast12ScopedQualification(t *testing.T){
 out:=os.Getenv("FAST12_QUAL_OUTPUT");if out==""{t.Fatal("explicit fresh FAST12_QUAL_OUTPUT required")};if e:=os.Mkdir(out,0755);e!=nil{t.Fatal(e)}
 rows:=[]map[string]interface{}{};carrier_rows:=[]map[string]interface{}{};negative_rows:=[]map[string]interface{}{};wrong_rows:=[]map[string]interface{}{};coarse_fail,fine_fail,carrier_fail,negative_fail,wrong_fail:=0,0,0,0,0;max_median,max_span,max_bound:=0.,0.,0.;dumped:=map[string]bool{}
 for _,rate:=range fast_rates{for _,shape:=range []string{"amplitude_saw","db_saw","db_stair128","db_stair256"}{for _,cp:=range []float64{0,.7,2.2}{for _,lp:=range []float64{0,.17,.61}{for _,age:=range []float64{-.5,.5}{for _,steps:=range []int{0,1024}{for _,quant:=range []string{"floor16","exponent_like"}{
  spec:=forward_spec{rate,shape,cp,lp,age,steps,quant,8170,65984,1};v,native_hash:=forward_native(spec);job:=fast_job(v,fast_nominal(rate));e:=job.analyze();fine:=fast_fine(&job,fast_nominal(rate));coarse:=e==nil&&job.result.State=="periodic_measured"&&job.result.Period!=nil&&job.result.Period.Bounds!=nil&&job.result.Period.Bounds[0]<=fast_nominal(rate)&&fast_nominal(rate)<=job.result.Period.Bounds[1]&&job.result.Gate!=nil&&job.result.Gate.Stable
  if !coarse{coarse_fail++};if !fine.Match{fine_fail++};max_median=math.Max(max_median,math.Abs(fine.MedianRelativeError));max_span=math.Max(max_span,math.Abs(fine.RelativeError));max_bound=math.Max(max_bound,fine.RelativeBound)
  row:=map[string]interface{}{"spec":spec,"native_frames":65536,"native_pcm_sha256":native_hash,"retained_sha256":sample_hash(v),"published_state":job.result.State,"published_period":job.result.Period,"coarse_guard":coarse,"fine":fine};if e!=nil{row["error"]=e.Error()};rows=append(rows,row)
  key:=fmt.Sprintf("%02x-%s",rate,shape);representative:=cp==0&&lp==.17&&age==-.5&&steps==1024&&quant=="floor16";if (representative||!coarse||!fine.Match)&&!dumped[key]{path:=filepath.Join(out,key+".csv");if e:=write_signal(path,v);e!=nil{t.Fatal(e)};row["signal_csv"]=path;dumped[key]=true}
 }}}}}}}
 for _,amp:=range []float64{2048,8170}{for _,cp:=range []float64{0,.7,2.2}{for _,age:=range []float64{-.5,.5}{for _,steps:=range []int{0,1024}{for _,quant:=range []string{"floor16","exponent_like"}{
  spec:=forward_spec{0xc0,"constant",cp,0,age,steps,quant,amp,65984,1};v,native_hash:=forward_native(spec);carrier,e:=fast_carrier(v,3072);job:=fast_job(v,0);analysis_error:=job.analyze();qualified:=e==nil&&carrier["qualified"]==true&&analysis_error==nil&&job.result.State=="no_resolved_modulation"&&job.result.Gate!=nil&&job.result.Gate.Stable;if !qualified{carrier_fail++};row:=map[string]interface{}{"spec":spec,"native_pcm_sha256":native_hash,"retained_sha256":sample_hash(v),"carrier":carrier,"published_state":job.result.State,"qualified":qualified};if e!=nil{row["error"]=e.Error()};carrier_rows=append(carrier_rows,row)
 }}}}}
 for _,rate:=range fast_rates{for _,scale:=range []float64{32./31,31./32,31./30,30./31}{
  spec:=forward_spec{rate,"db_stair256",.7,.17,.5,1024,"floor16",8170,65984,scale};v,h:=forward_native(spec);job:=fast_job(v,fast_nominal(rate));e:=job.analyze();fine:=fast_fine(&job,fast_nominal(rate));rejected:=e==nil&&!fine.Match;if !rejected{wrong_fail++};wrong_rows=append(wrong_rows,map[string]interface{}{"spec":spec,"native_pcm_sha256":h,"retained_sha256":sample_hash(v),"published_state":job.result.State,"fine":fine,"wrong_rate_distinguished":rejected})
 }}
 for _,kind:=range []string{"quiet","stuck","tiny","noise","drift","clipped","short"}{
  spec:=forward_spec{0xc0,kind,.7,.17,.5,1024,"floor16",8170,65984,1};if kind=="tiny"{spec.Amplitude=16};if kind=="clipped"{spec.Amplitude=40000};v,h:=forward_native(spec);if kind=="short"{v=v[:8192]};job:=fast_job(v,fast_nominal(0xc0));e:=job.analyze();fine:=fast_fine(&job,fast_nominal(0xc0));rejected:=e==nil&&!fine.Match;if !rejected{negative_fail++};negative_rows=append(negative_rows,map[string]interface{}{"kind":kind,"native_pcm_sha256":h,"retained_sha256":sample_hash(v),"published_state":job.result.State,"fine":fine,"unqualified_retained":rejected});if e!=nil{negative_rows[len(negative_rows)-1]["error"]=e.Error()}
 }
 legal:=forward_spec{0xc0,"constant",.7,0,0,0,"floor16",8170,65984,1};alias:=legal;alias.NativeIncrement+=1<<18;left,_:=forward_native(legal);right,_:=forward_native(alias);alias_identical:=sample_hash(left)==sample_hash(right);metadata_reject:=alias.NativeIncrement*4>=1<<19
 if !alias_identical||!metadata_reject{negative_fail++};negative_rows=append(negative_rows,map[string]interface{}{"kind":"alias_nonidentifiability","legal_increment":legal.NativeIncrement,"illegal_increment":alias.NativeIncrement,"retained_bytes_identical":alias_identical,"metadata_nyquist_guard_rejects":metadata_reject,"limits":"Carrier fit alone cannot recover a preexisting alias; native/stride provenance and metadata guard are mandatory"})
 fine_qualified:=fine_fail==0&&wrong_fail==0&&coarse_fail==0&&carrier_fail==0&&negative_fail==0
 result:=map[string]interface{}{"state":"scoped_generic_qualification_completed","positive_count":len(rows),"carrier_null_count":len(carrier_rows),"wrong_rate_count":len(wrong_rows),"negative_count":len(negative_rows),"coarse_failures":coarse_fail,"fine_failures":fine_fail,"carrier_null_failures":carrier_fail,"wrong_rate_failures":wrong_fail,"negative_failures":negative_fail,"coarse_qualified":coarse_fail==0&&carrier_fail==0&&negative_fail==0,"fine_one_percent_qualified":fine_qualified,"maximum_median_relative_error":max_median,"maximum_span_relative_error":max_span,"maximum_relative_propagated_bound":max_bound,"positives":rows,"carrier_nulls":carrier_rows,"wrong_rates":wrong_rows,"negatives":negative_rows,"limits":[]string{"Independent generic forward PCM only, no chip model algorithm or capture","Published observer unchanged except command-main rename; all states/bands retained","Fine1% screen remains scoped and requires ROOTreview; failures never widened","No models, hardware, permanent or production edits; slowstairs not executed"}}
 if e:=write_json(filepath.Join(out,"qualification.json"),result);e!=nil{t.Fatal(e)};t.Logf("positives%d coarsefail%d finefail%d carrier%d/%d wrongfail%d/%d negativefail%d/%d maxmedian%.9g maxspan%.9g maxbound%.9g finequalified%v",len(rows),coarse_fail,fine_fail,carrier_fail,len(carrier_rows),wrong_fail,len(wrong_rows),negative_fail,len(negative_rows),max_median,max_span,max_bound,fine_qualified)
 if coarse_fail+fine_fail+carrier_fail+wrong_fail+negative_fail>0{t.Errorf("retained qualification failures; see qualification.json; fine diagnostic remains pending unless entire grid qualifies")}
}
func forward_native(s forward_spec)([]float64,string){
 const frames=65536;const pad=8;period:=fast_nominal(s.Rate)*4*s.PeriodScale;amplitudes:=make([]float64,frames+pad*2);phase_units:=make([]float64,len(amplitudes));random:=uint32(0x91b45e37);noise:=.5
 for k:=range amplitudes{n:=k-pad;phase_units[k]=float64(int64(n)*int64(s.NativeIncrement));q:=s.LFOPhase;if n>=4096{q+=float64(n-4096)/period};q-=math.Floor(q);switch s.Shape{case "db_stair128":q=math.Floor(q*128)/128;case "db_stair256":q=math.Floor(q*256)/256}
  gain:=math.Pow(10,-12*(1-q)/20);switch s.Shape{case "amplitude_saw":gain=.25+.75*q;case "constant","tiny":gain=1;case "quiet":gain=0;case "stuck":gain=1;case "noise":if n>=4096&&n%31==0{random^=random<<13;random^=random>>17;random^=random<<5;noise=.25+.75*float64(random&65535)/65535};gain=noise;case "drift":gain=.4;if n>=4096{gain+=.5*float64(n-4096)/float64(frames-4096)}};amplitudes[k]=s.Amplitude*gain
 }
 native:=make([]float64,frames)
 for n:=range native{at:=float64(n+pad)+s.Age;k:=int(math.Floor(at));f:=at-float64(k);units:=phase_units[k]+f*(phase_units[k+1]-phase_units[k]);phase:=s.CarrierPhase+2*math.Pi*math.Mod(units,float64(1<<20))/(1<<20);if s.PhaseSteps>0{step:=2*math.Pi/float64(s.PhaseSteps);phase=step*math.Floor(phase/step)};a:=amplitudes[k]+f*(amplitudes[k+1]-amplitudes[k]);value:=a*math.Sin(phase);if s.Shape=="stuck"{value=1000};if s.Shape=="clipped"{value=math.Max(-32767,math.Min(32767,value))};quantum:=16.;if s.Quantizer=="exponent_like"{quantum=1;for math.Abs(value)>511*quantum&&quantum<64{quantum*=2}};native[n]=quantum*math.Floor(value/quantum)
 }
 retained:=make([]float64,frames/4);for n:=range retained{retained[n]=native[n*4]};return retained,sample_hash(native)
}
func sample_hash(v []float64)string{data:=make([]byte,len(v)*8);for i,x:=range v{binary.LittleEndian.PutUint64(data[i*8:],math.Float64bits(x))};return fmt.Sprintf("%x",sha256.Sum256(data))}
func write_signal(path string,v []float64)error{f,e:=os.OpenFile(path,os.O_CREATE|os.O_EXCL|os.O_WRONLY,0600);if e!=nil{return e};w:=csv.NewWriter(f);if e=w.Write([]string{"sample","linear"});e!=nil{f.Close();return e};for n,x:=range v{if e=w.Write([]string{strconv.Itoa(n),strconv.FormatFloat(x,'f',-1,64)});e!=nil{f.Close();return e}};w.Flush();e=w.Error();close_error:=f.Close();if e!=nil{return e};return close_error}
func write_json(path string,v interface{})error{raw,e:=json.MarshalIndent(v,"","  ");if e!=nil{return e};f,e:=os.OpenFile(path,os.O_CREATE|os.O_EXCL|os.O_WRONLY,0600);if e!=nil{return e};_,e=f.Write(append(raw,'\n'));close_error:=f.Close();if e!=nil{return e};return close_error}

func TestExportFrozenCLIInputs(t *testing.T){
 out:=os.Getenv("FAST12_CLI_INPUTS");report:=os.Getenv("FAST12_QUAL_REPORT");if out==""||report==""{t.Fatal("explicit report/freshout required")};raw,e:=os.ReadFile(report);if e!=nil{t.Fatal(e)};var q map[string]interface{};if e=json.Unmarshal(raw,&q);e!=nil{t.Fatal(e)};if e=os.Mkdir(out,0755);e!=nil{t.Fatal(e)}
 for _,kind:=range []string{"carrier","quiet","clipped"}{
  shape:=kind;amp:=8170.;if kind=="carrier"{shape="constant"};if kind=="clipped"{amp=40000};lp:=.17;if kind=="carrier"{lp=0};spec:=forward_spec{0xc0,shape,.7,lp,.5,1024,"floor16",amp,65984,1};v,_:=forward_native(spec);h:=sample_hash(v);field:="negatives";if kind=="carrier"{field="carrier_nulls"};matches:=0;for _,entry:=range q[field].([]interface{}){if entry.(map[string]interface{})["retained_sha256"]==h{matches++}};if matches<1{t.Fatal("reproduced CLI input not present in frozen qualification grid",kind,h)};if e=write_signal(filepath.Join(out,kind+".csv"),v);e!=nil{t.Fatal(e)}
 };t.Log("Reproduced3 frozen-grid inputs; no new qualification grid or guard")
}
